"""Task-local validation for webhook_endpoint.py.

Runs the endpoint implementation against synthetic Stripe events using
minimal stubs for flask/stripe so no network or third-party install is needed.
"""

import ast
import json
import sys
import types

SOURCE_PATH = "webhook_endpoint.py"
with open(SOURCE_PATH, "r", encoding="utf-8") as fh:
    source = fh.read()

# 1. Syntax check
compile(source, SOURCE_PATH, "exec")
ast.parse(source)


class SignatureVerificationError(Exception):
    pass


class StripeError(Exception):
    pass


class _ConstructedEvent:
    def __init__(self, event_id, event_type, obj):
        self.id = event_id
        self.type = event_type
        self.data = {"object": obj}


def make_intent(intent_id, status, customer="cus_123", amount=2000,
                message=None):
    intent = {"id": intent_id, "customer": customer, "amount": amount,
              "metadata": {"order_id": "order_1"}}
    if message:
        intent["last_payment_error"] = {"message": message}
    return intent


def make_event(event_id, event_type, obj):
    return _ConstructedEvent(event_id, event_type, obj)


def construct_event(payload, sig_header, secret):
    if sig_header == "tampered":
        raise SignatureVerificationError("Signature verification failed")
    if sig_header != "valid":
        raise ValueError("Invalid payload")
    if payload is None:
        raise ValueError("Invalid payload")
    event = json.loads(payload.decode("utf-8"))
    return make_event(event["id"], event["type"], event["data"]["object"])


stripe = types.ModuleType("stripe")
stripe.Webhook = types.SimpleNamespace(construct_event=construct_event)
stripe.error = types.SimpleNamespace(
    SignatureVerificationError=SignatureVerificationError,
    StripeError=StripeError,
)


class _RouteRegistry:
    def __init__(self):
        self.routes = {}

    def route(self, rule, **kwargs):
        def decorator(fn):
            self.routes[rule] = fn
            return fn
        return decorator


class FakeFlask:
    def __init__(self, name):
        self.name = name
        self.routes = {}

    def route(self, rule, **kwargs):
        def decorator(fn):
            self.routes[rule] = fn
            return fn
        return decorator


class FakeRequest:
    def __init__(self, data, sig_header):
        self.data = data
        self.headers = {"Stripe-Signature": sig_header}


class FakeLogger:
    def __init__(self):
        self.lines = []

    def _record(self, level, msg, *args):
        self.lines.append(f"{level}: {msg % args if args else msg}")

    def info(self, msg, *args):
        self._record("info", msg, *args)

    def warning(self, msg, *args):
        self._record("warning", msg, *args)

    def error(self, msg, *args):
        self._record("error", msg, *args)


flask_mod = types.ModuleType("flask")
flask_mod.Flask = FakeFlask

ns = {"__name__": "webhook_endpoint_test", "__file__": SOURCE_PATH}
exec(compile(source, SOURCE_PATH, "exec"), ns)

app = ns["app"]
webhook_fn = app.routes["/webhook"]

logger = FakeLogger()
ns["logger"] = logger
ns["request"] = FakeRequest(b"", "valid")


def invoke(event, sig_header="valid"):
    ns["request"] = FakeRequest(
        json.dumps({
            "id": event.id,
            "type": event.type,
            "data": event.data,
        }).encode("utf-8"),
        sig_header,
    )
    return webhook_fn()


# 2. payment_intent.succeeded -> 200, success path taken
succeeded = make_event("evt_success", "payment_intent.succeeded",
                       make_intent("pi_success_1", "succeeded"))
status, code = invoke(succeeded)
assert code == 200, f"expected 200, got {code}"
assert any("Payment succeeded" in line for line in logger.lines), logger.lines

# 3. payment_intent.payment_failed -> 200, failure path taken
failed = make_event("evt_failure", "payment_intent.payment_failed",
                    make_intent("pi_failure_1", "requires_payment_method",
                                message="Your card was declined."))
status, code = invoke(failed)
assert code == 200, f"expected 200, got {code}"
assert any("Payment failed" in line for line in logger.lines), logger.lines

# 4. Tampered signature -> 400 "Invalid signature"
ns["request"] = FakeRequest(b"{}", "tampered")
body, code = webhook_fn()
assert code == 400 and body == "Invalid signature", (body, code)

# 5. Invalid payload -> 400 "Invalid payload"
ns["request"] = FakeRequest(b"not-json", "anything")
body, code = webhook_fn()
assert code == 400 and body == "Invalid payload", (body, code)

# 6. Idempotency: replaying the same event id is acknowledged without
#    double-processing (handler log lines must not double for the intent).
before = len([l for l in logger.lines if "Payment succeeded" in l])
status, code = invoke(succeeded)
assert code == 200
after = len([l for l in logger.lines if "Payment succeeded" in l])
assert after == before, f"event re-processed: {before} -> {after}"

print("ALL VALIDATION CHECKS PASSED")
